// Pulls original lead details from Read Leads1 and combines them 
// with the AI Agent's output text.

const aiItems = $input.all();
const leadRows = $('Read Leads1').all().map(n => n.json);
const out = [];

for (let i = 0; i < aiItems.length; i++) {
  const aiItem = aiItems[i]?.json || {};

  // Fall back to matching index from the Read Leads1 node if properties were dropped
  const originalLead = leadRows[i] || {};

  const username = aiItem.username || originalLead.username || 'unknown_user';
  const niche = aiItem.niche || originalLead.niche || 'small business';
  const score = aiItem.score || originalLead.score || 0;
  const step = aiItem.step || Number(originalLead.step || 0) + 1;

  // The AI Agent outputs its response in the .output property
  const rawResponse = aiItem.output || aiItem.text || '{}';

  let parsed = {};
  try {
    const cleanJson = typeof rawResponse === 'string'
      ? rawResponse.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim()
      : rawResponse;
    parsed = typeof cleanJson === 'string' ? JSON.parse(cleanJson) : cleanJson;
  } catch (err) {
    parsed = {};
  }

  let messageText = String(parsed.message_text || originalLead.base_template || '').trim();
  const whySend = String(
    parsed.why_send || `Strong ${niche} prospect (Score: ${score}).`
  ).trim();

  // Enforce mandatory opt-out footer
  if (messageText && !/stop/i.test(messageText)) {
    messageText = `${messageText}\n\nReply STOP to opt out.`;
  }

  const todayStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');

  out.push({
    json: {
      queue_id: `Q-${todayStr}-${username}-${step}`,
      username: username,
      profile_url: `https://www.instagram.com/${username}/`,
      step: step,
      niche: niche,
      score: score,
      why_send: whySend,
      message_text: messageText,
      status: 'pending',
      created_at: aiItem.now_iso || new Date().toISOString(),
      sent_by: '',
      sent_at: ''
    }
  });
}

return out;

